import test from 'node:test';import assert from 'node:assert/strict';
import {techniquePreview} from '../technique-preview.js';import {Battle,makeEnemy} from '../battle.js';import {defaultHero,compileTechnique,CORES,SUPPORTS} from '../mako.js';
function setup(){const hs=[defaultHero(0,4),defaultHero(1,4)];hs.forEach((h,i)=>{h.x=i;h.y=0;});const e=makeEnemy('predator',3);e.x=3;e.y=0;e.hp=e.maxHp=100000;const b=new Battle({heroes:hs,enemies:[e]});hs.forEach(h=>h.atb=1);return b;}
test('all recipe previews leave the live encounter untouched and quote the resource payment actually used',()=>{for(const c of CORES)for(const s of SUPPORTS){const b=setup(),h=b.heroes[0],t=compileTechnique(c.id,s.id),before=b.snapshot(),p=techniquePreview(b,h,t);assert.deepEqual(b.snapshot(),before);const target=t.healing?b.heroes[1]:b.enemies[0];assert.equal(b.command(h.id,'tech',target.id,t),p.enabled,t.name);assert.equal(h.mp,before.heroes[0].mp-p.mp,t.name);assert.equal(h.strain,before.heroes[0].strain+p.strain,t.name);}});
test('overdraw explicitly quotes HP and unsafe casts explain a recovery action',()=>{const b=setup(),h=b.heroes[0],t=compileTechnique('flame');h.mp=0;let p=techniquePreview(b,h,t);assert.equal(p.enabled,true);assert.equal(p.hp,t.cost*3);assert.match(p.costText,/HP overdraw/);h.hp=p.hp;p=techniquePreview(b,h,t);assert.equal(p.enabled,false);assert.match(p.reason,/Guard or use an Ether/);h.hp=h.maxHp;h.strain=99;p=techniquePreview(b,h,t);assert.equal(p.enabled,false);assert.match(p.reason,/strain.*Guard/);});
test('Link and readiness previews track actual partner charge without paying it',()=>{const b=setup(),h=b.heroes[0],ally=b.heroes[1],t=compileTechnique('earth','link');ally.atb=.49;assert.match(techniquePreview(b,h,t).reason,/half a gauge/);ally.atb=.5;assert.deepEqual(techniquePreview(b,h,t).partners,[ally.id]);assert.equal(ally.mp,ally.maxMp);h.atb=.9;assert.match(techniquePreview(b,h,t).reason,/Gathering focus/);});
